before:
```react
function KeyNotice() {
  const [key, setKey] = React.useState("");
  React.useEffect(() => {
    function receive(event) { setKey(event.key); }
    window.addEventListener("keydown", receive);
    return () => window.removeEventListener("keydown", receive);
  }, []);
  return <p>Last key: {key}</p>;
}
function App() { return <KeyNotice />; }
```
The cleanup removes the same listener function that setup added.

after:
```react
function KeyNotice() {
  const [key, setKey] = React.useState("");
  React.useEffect(() => {
    function receive(event) {
      setKey(event.key);
    }
    window.addEventListener("keydown", receive);
    return () => window.removeEventListener("keydown", receive);
  }, []);
  return <p>Last key: {key}</p>;
}
function App() {
  return <KeyNotice />;
}
```
A key press updates the message. When KeyNotice is removed, cleanup removes the same receive function that setup added.
